import { useState, type ChangeEvent, type FormEvent } from 'react';
import { Button } from '@jinx-ui/react';

export interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

export interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

type FieldDef = {
  key: keyof RegistrationData;
  label: string;
  type: string;
  autoComplete: string;
};

const STEPS: ReadonlyArray<{ title: string; fields: ReadonlyArray<FieldDef> }> = [
  {
    title: 'Контакты',
    fields: [
      { key: 'fullName', label: 'Имя и фамилия', type: 'text', autoComplete: 'name' },
      { key: 'email', label: 'Email', type: 'email', autoComplete: 'email' },
      { key: 'phone', label: 'Телефон', type: 'tel', autoComplete: 'tel' },
    ],
  },
  {
    title: 'Адрес',
    fields: [
      { key: 'country', label: 'Страна', type: 'text', autoComplete: 'country-name' },
      { key: 'city', label: 'Город', type: 'text', autoComplete: 'address-level2' },
      { key: 'street', label: 'Улица, дом, квартира', type: 'text', autoComplete: 'street-address' },
      { key: 'zip', label: 'Индекс', type: 'text', autoComplete: 'postal-code' },
    ],
  },
  { title: 'Проверка', fields: [] },
];

const EMPTY_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const ALL_FIELDS: ReadonlyArray<FieldDef> = [...STEPS[0].fields, ...STEPS[1].fields];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY_DATA);

  const step = STEPS[stepIndex];
  const isFirst = stepIndex === 0;
  const isLast = stepIndex === STEPS.length - 1;

  const update = (key: keyof RegistrationData) => (event: ChangeEvent<HTMLInputElement>) => {
    const { value } = event.target;
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(data);
      return;
    }
    setStepIndex((index) => Math.min(index + 1, STEPS.length - 1));
  };

  return (
    <form
      className="jx-card jx-stack"
      onSubmit={handleSubmit}
      aria-label="Регистрация"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-5, 20px)',
        padding: 'var(--jx-space-5, 20px)',
        borderRadius: 'var(--jx-radius, 4px)',
      }}
    >
      <ol
        className="jx-stepper"
        style={{
          display: 'flex',
          listStyle: 'none',
          margin: 0,
          padding: 0,
          gap: 'var(--jx-space-3, 12px)',
        }}
      >
        {STEPS.map((item, index) => {
          const state = index === stepIndex ? 'current' : index < stepIndex ? 'done' : 'todo';
          return (
            <li
              key={item.title}
              className={`jx-stepper__item jx-stepper__item--${state}`}
              aria-current={index === stepIndex ? 'step' : undefined}
              style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--jx-space-2, 8px)',
                padding: 'var(--jx-space-2, 8px)',
                borderRadius: 'var(--jx-radius, 4px)',
                borderBottom: '2px solid',
                borderBottomColor:
                  index <= stepIndex ? 'var(--jx-accent)' : 'var(--jx-border)',
                color: index === stepIndex ? 'var(--jx-fg)' : 'var(--jx-fg-muted)',
              }}
            >
              <span className="jx-stepper__index" aria-hidden="true">
                {index + 1}
              </span>
              <span className="jx-stepper__label">{item.title}</span>
            </li>
          );
        })}
      </ol>

      <section
        className="jx-stack"
        aria-labelledby="jx-wizard-step-title"
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}
      >
        <h2 id="jx-wizard-step-title" className="jx-heading">
          {step.title}
        </h2>

        {isLast ? (
          <dl
            className="jx-list"
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 2fr)',
              gap: 'var(--jx-space-2, 8px) var(--jx-space-4, 16px)',
              margin: 0,
            }}
          >
            {ALL_FIELDS.map((field) => (
              <div key={field.key} style={{ display: 'contents' }}>
                <dt className="jx-label" style={{ color: 'var(--jx-fg-muted)' }}>
                  {field.label}
                </dt>
                <dd style={{ margin: 0, color: 'var(--jx-fg)' }}>{data[field.key] || '—'}</dd>
              </div>
            ))}
          </dl>
        ) : (
          step.fields.map((field) => (
            <div
              key={field.key}
              className="jx-field"
              style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1, 4px)' }}
            >
              <label className="jx-label" htmlFor={`jx-wizard-${field.key}`}>
                {field.label}
              </label>
              <input
                id={`jx-wizard-${field.key}`}
                className="jx-input"
                type={field.type}
                name={field.key}
                autoComplete={field.autoComplete}
                value={data[field.key]}
                onChange={update(field.key)}
              />
            </div>
          ))
        )}
      </section>

      <div
        className="jx-actions"
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3, 12px)',
        }}
      >
        <Button
          type="button"
          variant="ghost"
          disabled={isFirst}
          onClick={() => setStepIndex((index) => Math.max(index - 1, 0))}
        >
          Назад
        </Button>
        <Button type="submit" variant="primary">
          {isLast ? 'Отправить' : 'Дальше'}
        </Button>
      </div>
    </form>
  );
}

